#![no_std]
use soroban_sdk::{contract, contracterror, contractimpl, contracttype, token, Address, Env};

/// Ledger counts for keeping storage alive: bump when fewer than THRESHOLD remain, up to EXTEND.
const LEDGER_THRESHOLD: u32 = 100_000;
const LEDGER_EXTEND: u32 = 518_400;

#[contracttype]
pub enum DataKey {
    /// The token contract that is staked (the native XLM Stellar Asset Contract in this project).
    Token,
    /// Total amount staked by everyone.
    Total,
    /// Amount staked by one user.
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq, PartialOrd, Ord)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contract]
pub struct Staking;

#[contractimpl]
impl Staking {
    /// Runs once at deploy time, so the contract is ready to use as soon as it is deployed.
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::Total, &0_i128);
        env.storage()
            .instance()
            .extend_ttl(LEDGER_THRESHOLD, LEDGER_EXTEND);
    }

    /// Transfers `amount` from `user` to this contract and credits it to their stake.
    pub fn stake(env: Env, user: Address, amount: i128) -> Result<(), Error> {
        user.require_auth();
        if amount <= 0 {
            return Err(Error::InvalidAmount);
        }

        let token = Self::token(&env);
        token::Client::new(&env, &token).transfer(&user, &env.current_contract_address(), &amount);

        let staked = Self::staked(env.clone(), user.clone());
        Self::write_staked(&env, &user, staked + amount);
        Self::write_total(&env, Self::total_staked(env.clone()) + amount);
        Ok(())
    }

    /// Returns `amount` of `user`'s stake to them. Fails if they have less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) -> Result<(), Error> {
        user.require_auth();
        if amount <= 0 {
            return Err(Error::InvalidAmount);
        }

        let staked = Self::staked(env.clone(), user.clone());
        if amount > staked {
            return Err(Error::InsufficientStake);
        }
        Self::write_staked(&env, &user, staked - amount);
        Self::write_total(&env, Self::total_staked(env.clone()) - amount);

        let token = Self::token(&env);
        token::Client::new(&env, &token).transfer(&env.current_contract_address(), &user, &amount);
        Ok(())
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        let key = DataKey::Staked(user);
        match env.storage().persistent().get::<_, i128>(&key) {
            Some(amount) => {
                env.storage()
                    .persistent()
                    .extend_ttl(&key, LEDGER_THRESHOLD, LEDGER_EXTEND);
                amount
            }
            None => 0,
        }
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        env.storage().instance().get(&DataKey::Total).unwrap_or(0)
    }

    fn token(env: &Env) -> Address {
        env.storage()
            .instance()
            .get(&DataKey::Token)
            .expect("token is set by the constructor")
    }

    fn write_staked(env: &Env, user: &Address, amount: i128) {
        let key = DataKey::Staked(user.clone());
        env.storage().persistent().set(&key, &amount);
        env.storage()
            .persistent()
            .extend_ttl(&key, LEDGER_THRESHOLD, LEDGER_EXTEND);
    }

    fn write_total(env: &Env, amount: i128) {
        env.storage().instance().set(&DataKey::Total, &amount);
        env.storage()
            .instance()
            .extend_ttl(LEDGER_THRESHOLD, LEDGER_EXTEND);
    }
}

mod test;
EOF
cat > contracts/contracts/staking/src/test.rs <<'EOF'
#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, token::StellarAssetClient, Address, Env};

struct Setup<'a> {
    env: Env,
    client: StakingClient<'a>,
    token: token::Client<'a>,
    user: Address,
}

fn setup() -> Setup<'static> {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let asset = env.register_stellar_asset_contract_v2(admin);
    let token_id = asset.address();
    let contract_id = env.register(Staking, (token_id.clone(),));
    let client = StakingClient::new(&env, &contract_id);

    let user = Address::generate(&env);
    StellarAssetClient::new(&env, &token_id).mint(&user, &1_000);

    Setup {
        token: token::Client::new(&env, &token_id),
        client,
        user,
        env,
    }
}

#[test]
fn stake_moves_tokens_and_records_stake() {
    let s = setup();
    s.client.stake(&s.user, &400);

    assert_eq!(s.client.staked(&s.user), 400);
    assert_eq!(s.client.total_staked(), 400);
    assert_eq!(s.token.balance(&s.user), 600);
    assert_eq!(s.token.balance(&s.client.address), 400);
}

#[test]
fn stakes_accumulate_per_user_and_in_total() {
    let s = setup();
    let other = Address::generate(&s.env);
    StellarAssetClient::new(&s.env, &s.token.address).mint(&other, &500);

    s.client.stake(&s.user, &100);
    s.client.stake(&s.user, &150);
    s.client.stake(&other, &50);

    assert_eq!(s.client.staked(&s.user), 250);
    assert_eq!(s.client.staked(&other), 50);
    assert_eq!(s.client.total_staked(), 300);
}

#[test]
fn unstake_returns_tokens_and_reduces_stake() {
    let s = setup();
    s.client.stake(&s.user, &400);
    s.client.unstake(&s.user, &150);

    assert_eq!(s.client.staked(&s.user), 250);
    assert_eq!(s.client.total_staked(), 250);
    assert_eq!(s.token.balance(&s.user), 750);
    assert_eq!(s.token.balance(&s.client.address), 250);
}

#[test]
fn unstake_everything_leaves_zero() {
    let s = setup();
    s.client.stake(&s.user, &400);
    s.client.unstake(&s.user, &400);

    assert_eq!(s.client.staked(&s.user), 0);
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.token.balance(&s.user), 1_000);
}

#[test]
fn unstake_more_than_staked_fails() {
    let s = setup();
    s.client.stake(&s.user, &100);

    let result = s.client.try_unstake(&s.user, &101);
    assert_eq!(result, Err(Ok(Error::InsufficientStake)));

    // Nothing moved.
    assert_eq!(s.client.staked(&s.user), 100);
    assert_eq!(s.client.total_staked(), 100);
    assert_eq!(s.token.balance(&s.user), 900);
}

#[test]
fn unstake_with_nothing_staked_fails() {
    let s = setup();
    let result = s.client.try_unstake(&s.user, &1);
    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
}

#[test]
fn non_positive_amounts_are_rejected() {
    let s = setup();
    assert_eq!(s.client.try_stake(&s.user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_stake(&s.user, &-5), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_unstake(&s.user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.total_staked(), 0);
}

#[test]
fn new_contract_reports_zero() {
    let s = setup();
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.client.staked(&s.user), 0);
}
EOF
cd contracts && timeout 900 cargo test -p staking 2>&1 | tail -60

