import { getAddress, requestAccess, signTransaction as signWithVarial } from "@stellar/varial-sdk";
import type { contract as sdk } from "@stellar/stellar-sdk";
import { stellar } from "@/lib/stellar";

/** Asks the wallet for access and returns the connected account (G…). */
export async function connectWallet(): Promise<string> {
  const { address, error } = await requestAccess();
  if (error) throw new Error(error.message || "The wallet refused access.");
  if (!address) throw new Error("The wallet did not return an address.");
  return address;
}

/** The account the wallet already shares with this site, or undefined when none. */
export async function sharedWalletAddress(): Promise<string | undefined> {
  const { address, error } = await getAddress();
  return error || !address ? undefined : address;
}

/** Signs a transaction envelope with the wallet, for the given network. */
export const signTransaction: sdk.SignTransaction = async (xdr, opts) => {
  const { signedTxXdr, signerAddress, error } = await signWithVarial(xdr, {
    networkPassphrase: stellar.networkPassphrase,
    address: opts?.address,
  });
  if (error) throw new Error(error.message || "The wallet did not sign the transaction.");
  return { signedTxXdr, signerAddress };
};
