"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";
import { stakingContract } from "@/lib/contracts";
import { connectWallet, sharedWalletAddress, signTransaction } from "@/lib/wallet";
import { useEffect } from "react";

export function StakingPanel() {
  const router = useRouter();
  const [address, setAddress] = useState<string | undefined>();
  const [amount, setAmount] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | undefined>();
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    sharedWalletAddress().then(setAddress).catch(() => undefined);
  }, []);

  async function onConnect() {
    setMessage(undefined);
    try {
      setAddress(await connectWallet());
    } catch (error) {
      setFailed(true);
      setMessage(error instanceof Error ? error.message : String(error));
    }
  }

  async function onStake(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setMessage(undefined);
    if (!address) {
      setFailed(true);
      setMessage("Connect a wallet first.");
      return;
    }
    if (!/^\d+$/.test(amount.trim()) || BigInt(amount.trim()) <= 0n) {
      setFailed(true);
      setMessage("Enter a whole number of stroops greater than zero.");
      return;
    }
    setBusy(true);
    try {
      const client = stakingContract({ publicKey: address, signTransaction });
      const tx = await client.stake({ user: address, amount: BigInt(amount.trim()) });
      await tx.signAndSend();
      setFailed(false);
      setMessage(`Staked ${amount.trim()} stroops.`);
      setAmount("");
      router.refresh();
    } catch (error) {
      setFailed(true);
      setMessage(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      <p>
        {address ? (
          <>
            Connected: <code data-testid="wallet-address">{address}</code>
          </>
        ) : (
          <button type="button" data-testid="connect-wallet" onClick={onConnect}>
            Connect wallet
          </button>
        )}
      </p>
      <form onSubmit={onStake}>
        <label>
          Amount to stake (stroops){" "}
          <input
            data-testid="stake-amount"
            type="text"
            inputMode="numeric"
            pattern="[0-9]*"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            disabled={busy}
          />
        </label>{" "}
        <button type="submit" data-testid="stake-submit" disabled={busy || !address}>
          {busy ? "Staking…" : "Stake"}
        </button>
      </form>
      {message && (
        <p role="status" data-testid={failed ? "stake-error" : "stake-status"}>
          {message}
        </p>
      )}
    </section>
  );
}
EOF
